// SwiftUI
struct NotificationRow: View {
    @State private var isOn = true

    var body: some View {
        JdToggle("알림 받기", isOn: $isOn)          // 가장 흔한 형태: 라벨 + 바인딩
        JdToggle(isOn: $isOn, size: .lg)            // 라벨 없이(트레이트는 시스템이 낭독)
        JdSwitch("동일 컨트롤", isOn: $isOn)         // 별칭 — JdToggle과 같은 타입
    }
}

